"""Build visual-only Habitat story scenes. No API, auth or commerce execution."""
from pathlib import Path
import json, html, re

ROOT=Path(__file__).resolve().parent.parent
ICONS=json.loads((ROOT/'source/icons.json').read_text())
def icon(name): return ICONS[name]
def link(text, dest, cls='link'): return f'<a class="{cls}" href="{dest}.html">{text}</a>'
def btn(text, dest): return link(text,dest,'button')
def photo(name,alt,cls=''): return f'<img class="{cls}" src="../assets/{name}.png" alt="{alt}">'
def field(label, value='', kind='text', help='', invalid=False, placeholder=''):
    fid='f-'+''.join(c for c in label.lower() if c.isalnum())
    return f'<div class="field"><label for="{fid}">{label}</label><input id="{fid}" type="{kind}" value="{html.escape(value,quote=True)}" placeholder="{placeholder}"'+(' aria-invalid="true" aria-describedby="'+fid+'-help"' if invalid else '')+f'>{f"<span id={fid}-help class=field-error>{help}</span>" if invalid else f"<span class=help>{help}</span>" if help else ""}</div>'
def note(text, cls=''): return f'<div class="note {cls}">{icon("Info")}<p>{text}</p></div>'
def bread(*parts): return '<div class="breadcrumb">'+f' {icon("ChevronRight")} '.join(parts)+'</div>'

def header():
    return f'''<a class="skip" href="#main">Skip to content</a><div class="announcement">Furniture for the way you live. Start with your room.</div><header class="site-header"><div class="wrap header-row"><button class="icon-button menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-menu">{icon('Menu')}</button>{link('HABITAT','01-home-top','wordmark')}<nav class="nav" aria-label="Main">{link('Rooms','01-home-top','')}{link('Furniture','03-collection','')}{link('Materials','02-home-bottom','')}{link('Measure your space','05-product-dimensions','')}</nav><div class="utilities">{link(icon('Search')+'<span class="sr-only">Search furniture</span>','03-collection','icon-button')}{link(icon('UserRound')+'<span class="sr-only">Your account</span>','12-profile','icon-button account-utility')}{link(icon('ShoppingBag')+'<span class="small">2</span><span class="sr-only">items in cart</span>','07-cart','icon-button')}</div></div><nav id="mobile-menu" class="mobile-menu" hidden aria-label="Mobile">{link('Living room','03-collection','')}{link('Furniture','03-collection','')}{link('Materials & care','02-home-bottom','')}{link('Measure your space','05-product-dimensions','')}{link('Your account','12-profile','')}</nav></header>'''

def footer():
    return f'''<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="wordmark">HABITAT</div><p>Objects to live with.<br>Materials to understand.<br>Room to make your own.</p></div><div><h4>Explore</h4>{link('Living room','03-collection','')}{link('Furniture','03-collection','')}{link('Materials & care','02-home-bottom','')}</div><div><h4>Here to help</h4>{link('Measurement guide','05-product-dimensions','')}{link('Delivery & returns','06-product-continuation','')}{link('Your orders','13-orders','')}</div></div><div class="footer-end"><span>© Habitat · India · INR ₹</span><span>Privacy &nbsp; · &nbsp; Terms &nbsp; · &nbsp; Powered by LetBuyy</span></div></div></footer>'''

def product_card(which):
    chair=which=='chair'
    name='Aara lounge chair' if chair else 'Nila side table'
    price='18,900' if chair else '6,400'
    facts='68 W × 78 D × 74 H cm' if chair else '50 Ø × 42 H cm'
    target='04-product-main' if chair else '06-product-continuation'
    return f'''<article class="product">{link(photo(which,name+' in natural teak'),target,'product-media')}<div class="product-meta"><h3>{link(name,target,'')}</h3><span class="product-price">₹{price}</span></div><div class="product-facts"><span>{facts}</span><span>Natural teak</span></div>{link('View chair & finishes' if chair else 'View table details',target)}</article>'''

def quantity(): return f'<div class="quantity" aria-label="Quantity"><button aria-label="Decrease quantity" data-quantity="-1">{icon("Minus")}</button><span data-count>1</span><button aria-label="Increase quantity" data-quantity="1">{icon("Plus")}</button></div>'
def finishes(): return f'''<fieldset><legend>Finish — <span data-finish-label>Natural teak</span></legend><div class="finishes"><button class="finish" data-finish="natural" aria-pressed="true"><span class="swatch"></span>Natural teak {icon('Check')}</button><button class="finish" data-finish="smoked" aria-pressed="false"><span class="swatch smoked"></span>Smoked teak</button></div></fieldset>'''
def context(): return f'<div class="wrap context-bar"><div><strong>Aara lounge chair</strong><span class="muted" data-variant-context>Natural teak · ₹18,900</span></div>{link("Back to selection "+icon("ArrowRight"),"04-product-main")}</div>'

def diagram():
    return '''<svg class="diagram" viewBox="0 0 520 380" role="img" aria-labelledby="diagram-title diagram-desc"><title id="diagram-title">Aara chair dimension diagram</title><desc id="diagram-desc">Assembled chair: width 68 centimetres, depth 78 centimetres, height 74 centimetres. Seat height 38 centimetres. Schematic, not to scale.</desc><path class="object" d="M132 244 L159 120 L329 120 L357 244 M156 242 L166 168 L323 168 L335 242 M143 244 L347 244 L333 270 L158 270 Z M159 270 L153 300 M331 270 L338 300 M170 170 L187 126 M202 170 L215 126 M235 170 L244 126 M270 170 L273 126 M305 170 L302 126"/><line x1="123" y1="325" x2="361" y2="325"/><path d="M130 319 L123 325 L130 331 M354 319 L361 325 L354 331"/><text x="242" y="355" text-anchor="middle">68 cm width</text><line x1="393" y1="118" x2="393" y2="300"/><path d="M387 125 L393 118 L399 125 M387 293 L393 300 L399 293"/><text x="425" y="208" text-anchor="middle" transform="rotate(-90 425 208)">74 cm height</text><line x1="94" y1="214" x2="94" y2="300"/><text x="72" y="262" text-anchor="middle" transform="rotate(-90 72 262)">38 cm seat</text><text x="260" y="65" text-anchor="middle">Depth front to back: 78 cm</text></svg>'''

def summary(quoted=False,mini=False):
    items=''
    if mini:
      for asset,name,price in [('chair','Aara lounge chair','18,900'),('table','Nila side table','6,400')]:
        items+=f'<div class="mini-line">{photo(asset,name)}<div><strong>{name}</strong><p>Natural teak · Qty 1</p></div><span>₹{price}</span></div>'
    return f'''<aside class="summary-box"><h3>{'Order summary' if quoted else 'Your cart summary'}</h3>{items}<div class="summary-row"><span>Items · 2</span><span>₹25,300</span></div><div class="summary-row"><span>Delivery</span><span>{'₹500' if quoted else 'At checkout'}</span></div><div class="summary-row"><span>Discount</span><span>₹0</span></div><div class="summary-row total"><span>{'Total' if quoted else 'Subtotal'}</span><span>₹{'25,800' if quoted else '25,300'}</span></div><p class="small">Tax included in item prices. {'Sample address-specific quote. No delivery date supplied.' if quoted else 'Delivery options and final total are confirmed after your address.'}</p>{'<span class="tag">Sample quote</span>' if quoted else btn('Continue to checkout '+icon('ArrowRight'),'08-checkout-address')}{'<p class="small">All amounts are fictional design fixtures.</p>' if quoted else ''}</aside>'''

def cart_line(which,qty=True):
    chair=which=='chair'; name='Aara lounge chair' if chair else 'Nila side table'; price='18,900' if chair else '6,400'
    facts='68 W × 78 D × 74 H cm' if chair else '50 Ø × 42 H cm'
    return f'''<article class="cart-line">{photo(which,name)}<div><h3>{name}</h3><p>Natural teak{' / Oatmeal cushion' if chair else ''}</p><p>{facts}</p>{quantity()+'<button class="remove" data-demo="Remove item">Remove</button>' if qty else '<p>Quantity 1</p>'}</div><span class="line-price">₹{price}</span></article>'''

def checkout_header(): return f'<header class="checkout-header"><div class="wrap">{link("HABITAT","01-home-top","wordmark")}<small>{icon("LockKeyhole")}Shared LetBuyy checkout</small></div></header>'
def checkout_footer(): return '<div class="checkout-footer"><span>Privacy &nbsp; · &nbsp; Terms &nbsp; · &nbsp; Returns policy</span><span>Powered by LetBuyy</span></div>'
def account_nav(active):
    return '<nav class="account-nav" aria-label="Your account">'+''.join(link(icon(ic)+text,dest,'active' if key==active else '') for key,text,dest,ic in [('profile','Profile','12-profile','UserRound'),('orders','Orders','13-orders','Package'),('addresses','Addresses','15-addresses','MapPin')])+link(icon('LogOut')+'Sign out','10-sign-in','')+'</nav>'
def account(content,active,title,sub):
    return header()+f'<main id="main" class="wrap page-bottom">{bread(link("Home","01-home-top",""),"Your account")}<div class="account-heading"><div><span class="eyebrow">Your Habitat account</span><h1>{title}</h1><p>{sub}</p></div>{link("Continue browsing "+icon("ArrowRight"),"03-collection")}</div><div class="account-layout">{account_nav(active)}<div class="account-main">{content}</div></div></main>'+footer()

SCENES=[]
def scene(sid,title,desc,body,identity=False,route=''):
    if sid=='09-checkout-review':
        pattern=r'(<div class="checkout-layout">)(<div><h1>One last look.*?)(<div class="checkout-summary">.*?)(</div><div class="checkout-footer">)'
        def reorder(m):
            return '<div class="checkout-layout review-checkout">'+m.group(3)+m.group(2).replace('<div>','<div class="checkout-main">',1)+m.group(4)
        body=re.sub(pattern,reorder,body,flags=re.S)
    SCENES.append({'id':sid,'title':title,'description':desc,'source':f'source/{sid}.html','productionRouteRole':route,'version':'habitat-design-1.0'})
    page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Habitat visual study</title><link rel="stylesheet" href="styles.css"><script src="prototype.js" defer></script></head><body data-scene="{sid}" class="{'identity' if identity else ''}">{body}<div class="sr-only" aria-live="polite" id="demo-status"></div></body></html>'''
    (ROOT/f'source/{sid}.html').write_text(page)

scene('01-home-top','Home · room discovery','Room index beside panoramic context; measurement guide before shopping.',header()+f'''<main id="main"><div class="wrap"><div class="hero-heading"><div><span class="eyebrow">The considered home</span><h1>A little room.<br>A lot of living.</h1></div><p class="lead">Find furniture for your space, with the dimensions and details to make it yours.</p></div><div class="room-hero"><nav class="room-index" aria-label="Shop by room"><span class="eyebrow">Start with a room</span>{link('Living '+icon('ArrowRight'),'03-collection','current')}{link('Dining '+icon('ArrowRight'),'03-collection','')}{link('Work '+icon('ArrowRight'),'03-collection','')}{link('Rest '+icon('ArrowRight'),'03-collection','')}<p class="small">A focused edit for everyday rooms.</p></nav><div class="room-image">{photo('room','Natural teak lounge chair and round table in a sunlit living room')}<div class="room-caption"><span>The living edit · Natural teak, soft linen</span>{link('Explore the living room '+icon('ArrowRight'),'03-collection')}</div></div></div><div class="guide-strip"><p>{icon('Ruler')} &nbsp;Start with the space you have.<br><span class="small">Room dimensions, doorways and access matter.</span></p>{link('Read the measuring guide','05-product-dimensions')}</div><div class="section-head rule" style="padding-top:30px"><div><span class="eyebrow">Objects with a purpose</span><h2>A place to pause.</h2></div>{link('Meet the pieces '+icon('ArrowRight'),'02-home-bottom')}</div></div></main>''',route='One homepage, opening segment')

scene('02-home-bottom','Home · objects & understanding','Two furniture objects, material education, measurement advice, delivery information and footer.',header()+f'''<main id="main"><section class="wrap section"><div class="section-head"><div><span class="eyebrow">The living edit · continued</span><h1>A place to pause.</h1></div><p>Two pieces. Their own place in your room.<br>Each sold separately.</p></div><div class="products">{product_card('chair')}{product_card('table')}</div></section><section class="wrap section rule"><div class="material-panel">{photo('chair','Visible teak frame and oatmeal linen cushion')}<div><span class="eyebrow">Know the material</span><h2>The grain is part<br>of the character.</h2><p>Our sample Aara chair pairs a solid teak frame with a removable linen-covered cushion. Natural grain varies between pieces.</p>{link('Materials, finish & care '+icon('ArrowRight'),'05-product-dimensions')}</div></div></section><section class="wrap section"><div class="education"><div><span class="eyebrow">Before you bring it home</span><h2>Measure twice.<br>Make room once.</h2><p>Check the furniture footprint and the route it will take to reach your room.</p>{link('See the full measuring guide','05-product-dimensions')}</div><ol class="measure-steps"><li><strong>01</strong><div><strong>Map your room</strong><p>Mark width and depth. Keep your own circulation space.</p></div></li><li><strong>02</strong><div><strong>Follow the access path</strong><p>Measure doors, stair turns and lifts against package dimensions.</p></div></li><li><strong>03</strong><div><strong>Check delivery conditions</strong><p>Read the merchant’s service terms before checkout.</p></div></li></ol></div></section><section class="wrap service-grid rule"><div>{icon('Ruler')}<h4>Dimensions, in the open</h4><p>Assembled and package measurements have separate labels.</p></div><div>{icon('Package')}<h4>Assembly, explained</h4><p>See the work needed before choosing a piece.</p></div><div>{icon('Truck')}<h4>Delivery, with context</h4><p>Options and charges depend on your actual address.</p></div></section></main>'''+footer(),route='Same homepage, continuation segment')

scene('03-collection','Living room · collection','Large two-up cards, dimensions, material/finish query concepts, real small-catalog pagination state.',header()+f'''<main id="main" class="wrap page-bottom">{bread(link('Home','01-home-top',''),'Rooms','Living')}<div class="collection-intro"><div><span class="eyebrow">A space to slow down</span><h1>The living room.</h1><p>A chair to settle into. A table to keep things close. Start with what fits.</p></div><div class="notice">{icon('Ruler')} &nbsp;Measurements are assembled size unless marked as package size.</div></div><nav class="category-rail" aria-label="Furniture type">{link('All living','03-collection','chip selected')}{link('Seating','04-product-main','chip')}{link('Side tables','06-product-continuation','chip')}</nav><div class="filter-row"><div><button class="chip" data-demo="Dimension filters">{icon('SlidersHorizontal')}Size & material</button><span class="tag">Width ≤ 70 cm</span><span class="tag">Natural teak</span><button class="link" data-demo="Clear finish filter">Clear finish</button></div><div><span>2 pieces</span><label class="sr-only" for="sort">Sort products</label><select id="sort"><option>Featured</option><option>Price: low to high</option></select></div></div><div class="products">{product_card('chair')}{product_card('table')}</div><div class="pager"><span>Showing 2 of 2 pieces</span><div class="pager-buttons"><button disabled aria-label="Previous page">{icon('ArrowLeft')}</button><button aria-current="page">1</button><button disabled aria-label="Next page">{icon('ArrowRight')}</button></div></div>{note('Need a smaller piece? Check its width, depth and height before comparing it with your space.')}</main>'''+footer(),route='Canonical paginated collection/search')

scene('04-product-main','Aara chair · selection','Panoramic room, object image, actual finish identities, common dimensions, price/availability and purchase action.',header()+f'''<main id="main" class="wrap">{bread(link('Home','01-home-top',''),link('Living','03-collection',''),'Aara lounge chair')}<figure class="pdp-panorama">{photo('room','Aara lounge chair and separate Nila table in a living room')}<figcaption>Room context · Chair and table sold separately.</figcaption></figure><div class="pdp-selection"><div class="pdp-object">{photo('chair','Aara lounge chair, natural teak finish','selected-product-image')}<div class="thumbs"><button aria-label="View chair object" data-gallery="chair">{photo('chair','Chair view')}</button><button aria-label="View room context" data-gallery="room">{photo('room','Room view')}</button></div></div><div class="pdp-info"><span class="eyebrow">Living / Seating</span><h1>Aara lounge chair</h1><div class="price" data-product-price>₹18,900</div><span class="small muted">Tax included · Price for selected finish</span><p>A low, open chair with a slatted teak back and a soft oatmeal cushion. Made for a quiet corner of your everyday room.</p><div class="facts-inline"><div><strong>68 × 78 × 74 cm</strong><span>Width × depth × height</span></div><div><strong>38 cm</strong><span>Seat height</span></div></div>{finishes()}<p class="availability">{icon('Check')}Available in this selected finish</p><div class="purchase-row">{quantity()}<button class="button" data-demo="Add selected chair to cart">Add to cart {icon('ArrowRight')}</button></div>{link('Review your cart','07-cart')}<div style="margin-top:22px">{link('Dimensions & access '+icon('Ruler'),'05-product-dimensions')}</div><p class="small">Solid teak frame · Removable linen-covered cushion<br>Chair arrives assembled. No tools needed.</p>{note('Delivery options and charges are confirmed at checkout. A delivery date is not available yet.')}{link('Read delivery conditions','06-product-continuation')}</div></div></main>''',route='One PDP, selection segment')

scene('05-product-dimensions','Aara chair · room fit & facts','Accessible dimension schematic, assembled/package distinction, variant updates and material/assembly information.',header()+context()+f'''<main id="main"><section class="wrap section"><div class="spatial"><div><span class="eyebrow">Make space for it</span><h1>Know every dimension.</h1><p class="lead">Measure the room it will live in, then the path it will take to get there.</p><div style="margin-top:28px">{diagram()}</div><p class="diagram-note">Schematic, not to scale. Exact text measurements below.</p>{note('Package size is not the chair’s assembled size. Check doors, stairs, turns and lifts against the package.')}</div><div class="stack"><div>{finishes()}<table class="facts-table"><caption>Dimensions · all values in cm</caption><tbody><tr><td>Assembled width</td><td>68 cm</td></tr><tr><td>Assembled depth</td><td>78 cm</td></tr><tr><td>Assembled height</td><td>74 cm</td></tr><tr><td>Seat height</td><td>38 cm</td></tr><tr><td>Package W × D × H</td><td data-package>72 × 82 × 78 cm</td></tr><tr><td>Product weight</td><td data-weight>13.8 kg</td></tr></tbody></table><p class="small">Assembled and seat dimensions are common to both finishes. Package size and weight belong to the selected variant.</p></div><div class="panel"><h3>Material & assembly</h3><table class="facts-table"><tbody><tr><td>Frame</td><td>Solid teak</td></tr><tr><td>Seat cover</td><td>Linen; removable</td></tr><tr><td>Cushion filling</td><td>Foam</td></tr><tr><td>Assembly</td><td>Arrives assembled</td></tr><tr><td>Tools required</td><td>None</td></tr></tbody></table><p class="small">Merchant-supplied sample facts. Grain and tone can vary naturally.</p></div></div></div><div class="finish-comparison"><h3>What changes with the finish?</h3><div class="finish-rows"><div class="panel"><strong>Natural teak · ₹18,900</strong><p>Assembled: 68 × 78 × 74 cm<br>Package: 72 × 82 × 78 cm · 13.8 kg</p></div><div class="panel"><strong>Smoked teak · ₹19,900</strong><p>Assembled: 68 × 78 × 74 cm<br>Package: 74 × 84 × 78 cm · 14.2 kg</p></div></div></div></section><section class="wrap section rule"><div class="section-head"><h2>Keep the details close.</h2>{link('Back to finish & purchase '+icon('ArrowRight'),'04-product-main')}</div><p>Keep your measurements alongside the selected finish. If a merchant has not supplied a critical dimension, ask before ordering.</p></section></main>''',route='Same PDP, decision-support segment')

scene('06-product-continuation','Aara chair · living with it','Care, actual delivery constraints, honest missing date and independent related table.',header()+context()+f'''<main id="main"><section class="wrap section"><div class="policy-grid"><div><span class="eyebrow">Living with Aara</span><h1>A little care.<br>A longer story.</h1><p style="margin-top:24px">Keep the teak frame dry and dust with a soft cloth. Blot spills promptly. Check the removable cover’s care label before cleaning.</p><details open><summary>Finish & natural variation</summary><p>Grain, knots and tone differ between pieces. Screen color is illustrative; the named finish identifies your selection.</p></details><details><summary>Cushion care</summary><p>Use the merchant-supplied care label for the supplied cover. Do not infer wash instructions from its appearance.</p></details></div><div class="panel"><span class="eyebrow">Before ordering</span><h2 style="margin-top:12px">Delivery & access</h2><p>Our sample service covers doorstep delivery where an eligible rate is returned for your address. Room placement and stair carry are not included in this fixture.</p><table class="facts-table"><tbody><tr><td>Assembly service</td><td>Not required; chair arrives assembled</td></tr><tr><td>Room placement</td><td>Not included in sample service</td></tr><tr><td>Delivery date</td><td>Not yet available</td></tr></tbody></table>{note('A pincode alone does not confirm a delivery date. Check the final service and charge at checkout.')}<details open><summary>Returns & damage reporting</summary><p>Check the merchant’s policy before purchase. Contact support from your order if the delivered item has a problem. Eligibility depends on the order and policy.</p></details></div></div></section><section class="wrap section rule"><div class="section-head"><div><span class="eyebrow">In the same room</span><h2>A place for the small things.</h2></div><p>Separately priced. Independently purchased.<br>No automatic bundle.</p></div><div class="two"><div>{photo('table','Nila side table in natural teak')}</div><div class="stack"><h3>Nila side table</h3><div class="price">₹6,400</div><p>A compact round table with intersecting slab legs. Natural teak finish, 50 cm diameter and 42 cm height.</p><table class="facts-table"><tbody><tr><td>Material</td><td>Solid teak</td></tr><tr><td>Package</td><td>56 × 56 × 48 cm</td></tr><tr><td>Assembly</td><td>Arrives assembled</td></tr></tbody></table>{link('Review table in cart '+icon('ArrowRight'),'07-cart')}<p class="small">Natural teak · Arrives assembled · Sold separately.</p></div></div></section></main>'''+footer(),route='Same chair PDP, supporting policy/related content; table has own production PDP')

scene('07-cart','Your cart','Selected natural finishes, exact dimensions, quantity/removal, arithmetic and checkout recovery.',header()+f'''<main id="main" class="wrap page-bottom"><div class="page-title"><span class="eyebrow">Your living edit</span><h1>Your cart.</h1><p>Two pieces, each with its own place.</p></div><div class="cart-layout"><div>{cart_line('chair')}{cart_line('table')}<div class="state-strip"><strong>Before you continue</strong><p>Check your selected finishes and access measurements. Prices and availability are checked again at checkout.</p></div>{link('Keep exploring the living room '+icon('ArrowRight'),'03-collection')}</div><div>{summary()}<div style="margin-top:20px">{note('Checkout unavailable? Your cart stays here. Retry when the connection returns; review any stock or price changes first.')}</div></div></div></main>'''+footer(),route='Canonical server cart')

address=field('Full name','Mira Rao')+field('Address line 1','Flat 2, Sample House')+field('Address line 2','Example Lane')+'<div class="form-grid">'+field('City','Pune')+field('Pincode','411001')+field('State','Maharashtra')+field('Country','India')+'</div>'
scene('08-checkout-address','Checkout · address','Canonical shared checkout, contact, destination, eligible shipping sample and complete summary.',checkout_header()+f'''<main id="main" class="checkout-wrap"><nav class="steps" aria-label="Checkout steps"><span class="active">1 &nbsp; Address</span>{icon('ChevronRight')}<span>2 &nbsp; Review & pay</span></nav><div class="checkout-layout"><div><h1>Where should it go?</h1><div class="review-card"><strong>Contact</strong><p>mira@example.test</p>{link('Use another account','10-sign-in')}</div><h3 style="margin:25px 0">Delivery address</h3><form data-demo-form>{address}<label class="check-row"><input type="checkbox" checked>Save this address to my LetBuyy account</label><h3 style="margin:30px 0 12px">Delivery option</h3><label class="shipping-option"><input type="radio" checked name="delivery"><div><strong>Standard doorstep delivery</strong><p>Sample eligible service · Date not supplied<br>Room placement and stair carry not included.</p></div><strong>₹500</strong></label><p class="small muted">Shown for the sample address. Final availability and charge come from the checkout quote.</p><div class="form-actions">{link('Return to cart','07-cart')}{btn('Review order '+icon('ArrowRight'),'09-checkout-review')}</div></form></div><div class="checkout-summary">{summary(True,True)}<div style="margin-top:20px">{note('Check package measurements against your access path. Delivery eligibility does not confirm that furniture will fit through your doorway.')}</div></div></div>{checkout_footer()}</main>''',route='Canonical hosted checkout, address step')

scene('09-checkout-review','Checkout · review & pay','Complete reviewed items/totals, eligible payment fixture and recoverable payment initiation error.',checkout_header()+f'''<main id="main" class="checkout-wrap"><nav class="steps" aria-label="Checkout steps"><span>1 &nbsp; Address</span>{icon('ChevronRight')}<span class="active">2 &nbsp; Review & pay</span></nav><div class="checkout-layout"><div><h1>One last look.</h1><p>Review the pieces, destination and delivery service before continuing.</p><div class="review-card"><div class="row"><strong>Contact</strong>{link('Change','08-checkout-address')}</div><p>mira@example.test</p></div><div class="review-card"><div class="row"><strong>Deliver to</strong>{link('Edit','08-checkout-address')}</div><p>Mira Rao<br>Flat 2, Sample House, Example Lane<br>Pune, Maharashtra 411001 · India</p></div><div class="review-card"><strong>Standard doorstep delivery · ₹500</strong><p>Date not supplied. Room placement and stair carry not included.</p></div><h3 style="margin:22px 0">Payment</h3><label class="payment-option selected"><input type="radio" name="payment" checked><div><strong>Pay online</strong><p>UPI, cards or net banking through the eligible provider.<br><span class="tag">Sample mode</span></p></div>{icon('CreditCard')}</label><div class="notice">Cash on delivery is unavailable for this sample cart.</div><div style="margin:22px 0">{note('Payment not started. The payment window did not open. Your details are kept; try opening it again.','error')}</div><p class="small muted">Continuing opens the provider’s payment step. It does not mark this order as paid.</p><button class="button block" style="margin:20px 0 12px" data-demo="Open eligible payment provider">Try payment again · ₹25,800 {icon('ArrowRight')}</button>{link('Back to address','08-checkout-address')}</div><div class="checkout-summary">{summary(True,True)}<p class="small muted" style="margin:20px 0">Selected finishes and quantities are shown above. The final quote is rechecked before commitment.</p></div></div>{checkout_footer()}</main>''',route='Same canonical hosted checkout, review/pay step')

def identity_shell(body,signup=False):
    aside=f'''<aside class="identity-aside"><div class="destination">{icon('ShoppingBag')}Your destination: <strong>Habitat</strong></div><h2>Your account.<br>Your way home.</h2><p>Use one LetBuyy buyer account across participating stores.</p><p class="small">Habitat shows only your orders with Habitat. Shared sign-in does not share every merchant’s data.</p>{link('Return to Habitat','01-home-top')}</aside>'''
    return f'<header class="identity-top"><img class="identity-logo" src="../assets/letbuyy-logo.svg" alt="LetBuyy"><span>Buyer account · Continuing to <strong>Habitat</strong></span></header><main id="main" class="identity-main">{aside}<section class="identity-card">{body}</section></main><footer class="identity-footer"><span>Privacy</span><span>Terms</span><span>Help</span></footer>'

scene('10-sign-in','LetBuyy · sign in for Habitat','Canonical credential branding, explicit destination, error/recovery and store-return consent context.',identity_shell(f'''<h1>Sign in</h1><p>Continue to Habitat with your LetBuyy account.</p><form data-demo-form>{field('Email','mira@example.test','email')}{field('Password','','password',placeholder='Enter your password')}<p class="small muted">Human verification appears here when required by the identity service.</p><button class="button block" data-demo="Canonical sign in" type="submit">Sign in {icon('ArrowRight')}</button></form><button class="link" data-demo="Open canonical password recovery">Forgot your password?</button><div class="verification"><p>New to LetBuyy?</p>{link('Create your account','11-sign-up')}</div><details><summary>What happens next?</summary><p>After signing in, confirm that Habitat may receive your email address. Then return to your store account.</p></details>'''),True,'Canonical identity-platform credential page')

scene('11-sign-up','LetBuyy · create & verify','Canonical registration, explicit signed-in Continue state, and separately explained optional email ownership verification.',identity_shell(f'''<h1>Create your LetBuyy account</h1><p>One account for Habitat and other participating LetBuyy stores.</p><form data-demo-form>{field('Email','mira@example.test','email')}{field('Password','','password','At least 8 characters.',placeholder='Create a password')}<p class="small muted">Human verification is handled by LetBuyy when required.</p><button class="button block" type="submit">Create account {icon('ArrowRight')}</button></form><p class="small">Already have an account? {link('Sign in','10-sign-in')}</p><div class="verification"><span class="tag">After credentials · confirm destination</span><h3 style="margin-top:16px">Continue to Habitat</h3><p>You’re signed in to LetBuyy as <strong>mira@example.test</strong>. Habitat will receive your email address.</p>{btn('Continue to Habitat '+icon('ArrowRight'),'12-profile')}{link('Use a different account','10-sign-in')}<details><summary>Email ownership verification</summary><p>Request a six-digit email code from your account when ownership proof is needed to link earlier orders. This is a separate action; it is not an automatic registration step or a condition for signing in.</p></details></div>''',True),True,'Canonical registration, with explicit signed-in Continue state; separate optional email ownership action')

scene('12-profile','Your Habitat profile','Store-scoped account shell, supported editing, verification, addresses and owned orders.',account(f'''<section class="panel"><div class="profile-top"><div class="avatar">MR</div><div><h2>Hello, Mira.</h2><p>mira@example.test</p><span class="tag status">{icon('Check')}Email verified · sample</span></div></div><h3 style="margin-bottom:20px">Your details</h3><form data-demo-form><div class="form-grid">{field('First name','Mira')}{field('Last name','Rao')}</div><div class="notice">Your sign-in email is managed by your LetBuyy buyer account.</div><div class="form-actions"><span class="small muted">No unsaved changes</span><button class="button" type="submit">Save changes</button></div></form></section><div class="account-panels"><section class="panel">{icon('Package')}<h3 style="margin-top:15px">Your Habitat orders</h3><p>See the pieces you have ordered from this store.</p>{link('View orders '+icon('ArrowRight'),'13-orders')}</section><section class="panel">{icon('MapPin')}<h3 style="margin-top:15px">Your addresses</h3><p>Review your saved delivery details before checkout.</p>{link('Manage addresses '+icon('ArrowRight'),'15-addresses')}</section></div><div class="state-strip"><strong>One account, store-specific history.</strong><p>This account view shows your Habitat relationship. Your sign-in belongs to LetBuyy.</p></div>''','profile','A familiar corner.','Your details, Habitat orders and saved delivery addresses.'),route='Canonical store account overview')

scene('13-orders','Your Habitat orders','Owned store order history with consistent ID/totals/status and precise direct-detail entry.',account(f'''<div class="section-head"><h2>Orders with Habitat</h2><span class="small muted">1 order · sample history</span></div><article class="order-card"><div class="order-card-head"><div><h3>HB-1042</h3><p>Placed 18 Oct 2026 · 2 items</p></div><span class="tag">Preparing · sample</span></div><div class="order-images">{photo('chair','Aara chair')}{photo('table','Nila table')}</div><p style="margin-top:18px">Aara lounge chair & Nila side table<br>Natural teak · Quantity 1 each</p><div class="order-card-foot"><div><strong class="price">₹25,800</strong><p class="small">Includes ₹500 delivery · sample payment recorded</p></div>{btn('View order '+icon('ArrowRight'),'14-order-detail')}</div></article><div class="pager"><span>Showing 1 of 1 order</span><span>Page 1 of 1</span></div>{note('Looking for an older order? Use the LetBuyy account with the email used for that order and verify ownership before linking it.')}{link('Review your profile','12-profile')}''','orders','Your orders.','The pieces you have ordered from Habitat, in one place.'),route='Canonical authenticated store order history')

scene('14-order-detail','Habitat order HB-1042','Owned order snapshot, exact variants/dimensions/totals, honest fulfillment and support context.',account(f'''<div class="order-card"><div class="order-card-head"><div><h2>Order HB-1042</h2><p style="margin-top:10px">Placed 18 Oct 2026 · Online payment</p></div><span class="tag">Sample order</span></div><div class="order-steps"><div class="order-step current"><strong>Order received</strong><p>18 Oct · sample record</p></div><div class="order-step current"><strong>Preparing</strong><p>No dispatch event yet</p></div><div class="order-step"><strong>Delivery</strong><p>Date not supplied</p></div></div>{cart_line('chair',False)}{cart_line('table',False)}<div class="two" style="margin-top:26px"><div><h3>Delivery destination</h3><p style="margin:15px 0">Mira Rao<br>Flat 2, Sample House<br>Example Lane, Pune<br>Maharashtra 411001 · India</p><p class="small">Standard doorstep delivery.<br>Room placement and stair carry not included in this sample service.</p></div><div><div class="summary-row"><span>Items</span><span>₹25,300</span></div><div class="summary-row"><span>Delivery</span><span>₹500</span></div><div class="summary-row"><span>Discount</span><span>₹0</span></div><div class="summary-row total"><span>Total</span><span>₹25,800</span></div><p class="small muted">Tax included. Payment recorded in fictional sample; no real transaction.</p></div></div></div><div class="state-strip"><strong>Need help with this order?</strong><p>Include HB-1042 when contacting Habitat. Tracking becomes available only after a real dispatch update.</p><button class="link" data-demo="Contact support for HB-1042">Contact Habitat support {icon('ArrowRight')}</button></div>{link('Back to all orders','13-orders')}''','orders','The details of your order.','Selected finishes and quantities remain part of the order record.'),route='Canonical directly addressable owned-order detail')

scene('15-addresses','Your saved addresses','Default address plus representative edit, invalid pincode recovery, cancel/save and explicit scope.',account(f'''<div class="address-layout"><section><div class="section-head"><h2>Saved addresses</h2></div><div class="address-card"><span class="tag">{icon('Check')}Default address</span><h4>Home · Mira Rao</h4><p>Flat 2, Sample House<br>Example Lane, Pune<br>Maharashtra 411001 · India</p><button class="link" data-demo="Edit saved Home address">Edit</button><button class="link" data-demo="Remove saved Home address">Remove</button></div><button class="button secondary block" style="margin-top:20px" data-demo="Add another address">{icon('Plus')}Add address</button><p class="small muted" style="margin-top:20px">Addresses belong to your LetBuyy buyer account. A merchant sees the delivery address shared with its order.</p></section><section class="panel"><span class="tag">Edit state · validation example</span><h3 style="margin-top:18px">Edit Home address</h3><form data-demo-form>{field('Full name','Mira Rao')}{field('Address line 1','Flat 2, Sample House')}{field('Address line 2','Example Lane')}<div class="form-grid">{field('City','Pune')}{field('Pincode','4110','text','Enter a 6-digit Indian pincode.',True)}{field('State','Maharashtra')}{field('Country','India')}</div><label class="check-row"><input type="checkbox" checked>Use as my default address</label>{note('Check the highlighted pincode. Your other edits are kept.','error')}<div class="form-actions"><button class="link" type="reset">Cancel</button><button class="button" type="submit">Save address</button></div></form></section></div>''','addresses','The way home.','Keep delivery details current. Eligibility is checked again at checkout.'),route='Canonical buyer address lifecycle')

